"""Layer 15, MLP neuron 5470 (its single rank-one component reads this unit).

Plain-terms summary: a detector for numbers in formulas, fractions, clock times and
decimals. It is strongest where a number is a simple value: a half (the 5 in "2.5"), a
fraction's denominator ("1/2"), minutes on a clock ("9:30"), or a +1 or -1 offset in a
formula ("n+1", "k-1"). About three quarters of the component's input weight is this one
MLP hidden unit, so its activation is that unit's value times a fixed scale.

The program reads only the two previous tokens and gives the average activation for each
pattern, measured on training text:
- a 5 right after a decimal point ("2.5"): about 4; a 0 there: slightly negative;
- a digit 2-5 after "/" (the denominator of "1/2"): about 2.5;
- a "/" after a number or letter (the start of a fraction): about 1.8;
- a 3, 4 or 5 after ":" (the minutes of a clock time): about 3;
- a 1 right after a sign ("-1", "+1"): about 2.5; other digits after a sign: about 0.5;
- a 0, 5 or 9 continuing a number ("20", "105"): about 0.7; other digits there: about 0;
- a sign right after a letter ("n+1", "k-1"): about 1.3; a sign after "=": about -2.5;
- everything else: 0.

It is small and readable, and on held-out rows it explains about 5% of the variance
(correlation about 0.22). The large spikes, mostly on the digits 5, 0 and 1, depend on
wider context than two tokens back, so most of the variance is not explained here.
"""

READS = ()

LETTERS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
DIGITS = set("0123456789")
SIGNS = {"+", "-", "−", "–"}


def kind(token):
    s = token.strip()
    if len(s) == 1 and s in DIGITS:
        return "digit"
    if s in SIGNS:
        return "sign"
    if s in ("/", ":", ".", "="):
        return s
    if len(s) == 1 and s in LETTERS:
        return "letter"
    return "other"


def step(carry, prefix, upstream):
    # The first token of a document has no earlier token in that document.
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if not same_doc:
        return None, 0.0
    before, now = prefix.token_strings[-2].strip(), prefix.token_strings[-1].strip()
    prev, cur = kind(before), kind(now)
    if cur == "digit":
        d = int(now)
        if prev == ".":
            return None, 4.0 if d == 5 else (-0.3 if d == 0 else 0.3)
        if prev == "/":
            return None, 2.5 if 2 <= d <= 5 else 0.5
        if prev == ":":
            return None, 3.0 if 3 <= d <= 5 else 0.2
        if prev == "sign":
            return None, 2.5 if d == 1 else 0.5
        if prev == "digit":
            return None, 0.7 if d in (0, 5, 9) else (0.2 if d == 8 else -0.2)
        return None, 0.0
    if cur == "/" and prev in ("digit", "letter"):
        return None, 1.8
    if cur == "sign":
        if prev == "letter":
            return None, 1.3
        if prev == "=":
            return None, -2.5
        if prev == "digit":
            return None, -0.3
    return None, 0.0

"""Layer 15 MLP hidden unit 5475 (the one its down_proj component reads, about 0.95 of
its input direction), as a word-level guess.

The unit is diffuse: its activation is mostly small noise, and its large negative values
sit in shell output, command flags, licence boilerplate and grade or level words. Its
large positive values sit on boolean and null literals. Local token identity explains
only about 2% of its variance, so this program is a sketch of its sign, not a fit.

Values are the least-squares means of each word group on a sample of training text.
"""

BOOLEAN_LITERALS = {"true", "false", "bool", "boolean", "none", "null"}
EXIT_STATUS_WORDS = {"exit", "exited", "completed", "finished", "finish", "pass", "ran", "reached", "status", "code", "rank"}
GRADE_LEVEL_WORDS = {"level", "levels", "grade", "grades", "medium", "moderate", "degree", "class", "score"}
LICENCE_WORDS = {"license", "licensed", "commons", "apache", "mit", "gpl", "creative"}
COMMAND_FLAGS = {"-x", "-r", "-m", "--", "-d", "-f", "-l", "-n", "-i"}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in BOOLEAN_LITERALS:
        return carry, 0.66
    if word in EXIT_STATUS_WORDS:
        return carry, -1.35
    if word in GRADE_LEVEL_WORDS:
        return carry, -0.37
    if word in LICENCE_WORDS:
        return carry, -0.5
    if word in COMMAND_FLAGS:
        return carry, -0.25
    return carry, 0.0
